<script setup lang="ts">
definePageMeta({ middleware:'auth' })
const form=reactive({name:'',type:'fixed' as 'fixed'|'percent',value:10,minSpend:100});const message=ref('');const {data:promotions,refresh}=await useFetch<any[]>('/api/promotions',{default:()=>[]})
async function save(){message.value='';try{await $fetch('/api/promotions',{method:'POST',body:form});form.name='';await refresh()}catch(e:any){message.value=e?.data?.statusMessage||'บันทึกไม่สำเร็จ'}}
async function toggle(p:any){await $fetch(`/api/promotions/${p.id}`,{method:'PATCH',body:{active:!p.active}});await refresh()}
</script>
<template><div><AppNav/><main class="admin-page"><div class="page-title"><div><p class="eyebrow">Campaigns</p><h1>โปรโมชัน</h1></div></div><form class="panel form-row" @submit.prevent="save"><label>ชื่อ<input v-model="form.name" required></label><label>ประเภท<select v-model="form.type"><option value="fixed">ลดเป็นบาท</option><option value="percent">ลดเป็นเปอร์เซ็นต์</option></select></label><label>มูลค่า<input v-model.number="form.value" type="number" min="1"></label><label>ยอดขั้นต่ำ<input v-model.number="form.minSpend" type="number" min="0"></label><button>เพิ่มโปรโมชัน</button><p v-if="message" class="error">{{message}}</p></form><div class="panel table-wrap"><table><thead><tr><th>ชื่อ</th><th>ส่วนลด</th><th>ยอดขั้นต่ำ</th><th>สถานะ</th><th></th></tr></thead><tbody><tr v-for="p in promotions" :key="p.id"><td><strong>{{p.name}}</strong></td><td>{{p.type==='percent'?`${p.value}%`:`${p.value} ฿`}}</td><td>{{p.minSpend}} ฿</td><td>{{p.active?'เปิด':'ปิด'}}</td><td><button class="secondary" @click="toggle(p)">{{p.active?'ปิด':'เปิด'}}</button></td></tr></tbody></table></div></main></div></template>
